parameters.jsCode:
const row = $json;

const approval = String(row["CRM Approval"] || "").trim();
const industry = String(row["Industry"] || "").toLowerCase();
const company = String(row["Company"] || "").toLowerCase();

// Board is selected by Benjamin through CRM Approval
const boardMap = {
  "Approved → Benjamin B2B": "B2B Pipeline (Benjamin)",
  "Approved → General B2B": "General Leads: Email Marketing",
  "Approved → Warm B2C": "B2C Pipeline (Warm Leads)",
};

const crmBoard = boardMap[approval] || "";

// Type is mapped only from verified company/industry data
const typeEvidence = `${industry} ${company}`;

let mondayType = "";

if (/aviation|airline|private jet|jet charter|charter/.test(typeEvidence)) {
  mondayType = "Aviation";
} else if (/travel|tour|travel agency|concierge|hospitality/.test(typeEvidence)) {
  mondayType = "Travel Company";
} else if (/property|villa|real estate/.test(typeEvidence)) {
  mondayType = "Property Management";
} else if (/membership|private club|family office/.test(typeEvidence)) {
  mondayType = "Membership";
}

// Required-field validation
const missingFields = [];

if (!row["Full Name"]) missingFields.push("Full Name");
if (!row["Title"]) missingFields.push("Title");
if (!row["Company"]) missingFields.push("Company");

if (!row["Email"] && !row["LinkedIn URL"]) {
  missingFields.push("Email or LinkedIn URL");
}

if (!mondayType) {
  missingFields.push("Verified Type");
}

if (!crmBoard) {
  missingFields.push("CRM Destination Approval");
}

return {
  json: {
    ...row,

    mondayAccount: row["Full Name"] || "",
    mondayEmail: row["Email"] || "",
    mondayLinkedIn: row["LinkedIn URL"] || "",
    mondayCompany: row["Company"] || "",
    mondayTitle: row["Title"] || "",
    mondayGPTSummary: row["Notes"] || "",
    mondayCompanyProfile: row["Company LinkedIn"] || "",
    mondayCompanyLinkedIn: row["Company LinkedIn"] || "",
    mondayCompanyURL: row["Website / Domain"] || "",
    mondayLocation: row["Location / City"] || "",
    mondayIndustry: row["Industry"] || "",
    mondayRevenue: row["Revenue"] || "",
    mondayFirstName: row["First Name"] || "",
    mondayLastName: row["Last Name"] || "",

    mondayType,
    mondayPlatform: "LINKEDIN",
    mondayLeadSource: "Apify",
    mondayStatus: "New Lead",

    mondayLastContact: "",
    mondayNextContact: "",
    mondayTP: "",

    mondayNotes: [
      row["Notes"] || "",
      "Source: Apify",
      "Platform: LinkedIn",
      `Sheet: B2B Travel Leads`,
      `Source Row: ${row["Source Row"] || row["row_number"] || ""}`,
      `Approved Destination: ${approval}`,
    ].filter(Boolean).join(" | "),

    crmBoard,
    isValidForCRM: missingFields.length === 0,
    missingFields: missingFields.join(", "),
  }
};

